<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Сгорают ли деньги на лицевом счёте 31 декабря?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Автоматического списания целевых средств с лицевого счёта участника казначейского сопровождения на рубеже года не происходит. К остаткам на 1 января применяется режим подтверждения потребности: подтверждённые продолжают использоваться, неподтверждённые перечисляются в доход бюджета по решению распорядителя."}}, {"@type": "Question", "name": "Почему заказчик требует закрыть акты до 20 декабря?", "acceptedAnswer": {"@type": "Answer", "text": "Потому что его лимиты прекращают действие 31 декабря, свободные остатки изымаются в резервный фонд уже 10–20 декабря, а казначейство принимает платёжные документы по уплотнённому графику. Заказчик хочет успеть оплатить в текущем году — для этого приёмка и платёжка должны пройти до предельных дат."}}, {"@type": "Question", "name": "До какой даты казначейство проводит платежи в декабре?", "acceptedAnswer": {"@type": "Answer", "text": "Предельные даты приёма и исполнения платёжных документов устанавливаются ежегодно актами Минфина и Федерального казначейства и различаются по видам операций. Ориентир — двадцатые числа декабря; точные даты своего года уточняйте в обслуживающем территориальном органе заранее."}}, {"@type": "Question", "name": "Что будет, если заказчик не успел оплатить контракт до конца года?", "acceptedAnswer": {"@type": "Answer", "text": "Обязательство не исчезает: в новом году оно перерегистрируется и оплачивается за счёт лимитов нового года. Срок оплаты по ст. 34 Закона № 44-ФЗ при этом не приостанавливается — за просрочку начисляются пени в размере 1/300 ключевой ставки за каждый день."}}, {"@type": "Question", "name": "Можно ли заключить госконтракт в конце декабря?", "acceptedAnswer": {"@type": "Answer", "text": "Можно, но с ограничением п. 14 Положения № 1496: после 1 декабря заказчик федерального бюджета не вправе принимать обязательства со сроками оплаты или выплаты аванса, превышающими один месяц после этой даты. Поэтому декабрьские контракты — короткие, с исполнением и оплатой до конца года."}}, {"@type": "Question", "name": "Что такое подтверждение потребности в остатках?", "acceptedAnswer": {"@type": "Answer", "text": "Решение главного распорядителя о том, что неиспользованные остатки целевых средств нужны для завершения расчётов по контракту или соглашению. По остаткам на 1 января 2026 года такое решение принимается до 1 мая 2026 года (ст. 5 Закона № 426-ФЗ); без него остатки возвращаются в бюджет."}}, {"@type": "Question", "name": "Нужно ли закрывать лицевой счёт в конце года, если контракт продолжается?", "acceptedAnswer": {"@type": "Answer", "text": "Нет. Лицевой счёт переходящего контракта продолжает действовать без перерегистрации, идентификатор не меняется. Закрытие счёта связано с завершением контракта и расчётов, а не с календарём."}}, {"@type": "Question", "name": "Почему в январе платежи «встают»?", "acceptedAnswer": {"@type": "Answer", "text": "Новому году нужны новые лимиты: пока они доведены до заказчика и обязательства перерегистрированы, финансирование стоит на паузе. Обычно это первые недели января–февраля. Средства, уже находящиеся на вашем лицевом счёте с подтверждённой потребностью, при этом расходуются в обычном режиме."}}, {"@type": "Question", "name": "Распространяются ли декабрьские дедлайны на региональные контракты?", "acceptedAnswer": {"@type": "Answer", "text": "Логика та же, но даты свои: регионы и муниципалитеты принимают собственные акты о завершении года. Если контракт финансируется из бюджета субъекта, календарь сверяйте с актами финоргана региона."}}, {"@type": "Question", "name": "Как конец года влияет на аванс?", "acceptedAnswer": {"@type": "Answer", "text": "Неотработанный аванс на лицевом счёте проходит ту же процедуру остатков: потребность подтверждается — аванс продолжает расходоваться в новом году. По завершённым или расторгнутым контрактам неотработанный аванс подлежит возврату заказчику."}}, {"@type": "Question", "name": "Есть ли случаи, когда прошлогодний контракт оплачивают в новом году по специальным правилам?", "acceptedAnswer": {"@type": "Answer", "text": "Да: для гособоронзаказа, международных обязательств и контрактов за счёт резервных фондов с поздними решениями Положение № 1496 допускает увеличение лимитов на оплату прошлогодних контрактов; такие расчёты завершаются не позднее 1 июня, затем санкционирование по этим лимитам приостанавливается."}}, {"@type": "Question", "name": "Что делать, если платёж завис в двадцатых числах декабря?", "acceptedAnswer": {"@type": "Answer", "text": "Сначала диагностика: возврат документа на доработку, очередь санкционирования или отсутствие лимитов у заказчика — это разные проблемы с разными решениями. Запросите статус в территориальном органе и у заказчика; если причина в документах — исправляйте немедленно, шанс успеть в текущий год ещё есть."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как исполнителю пройти конец года без потери оплаты", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Составить календарь года в октябре", "text": "Свести дедлайны: этапы к сдаче, нормативные сроки приёмки и оплаты, предельные даты приёма платёжных документов казначейством и внутренние даты заказчика."}, {"@type": "HowToStep", "position": 2, "name": "Сдать работы в первой половине декабря", "text": "Предъявить результаты так, чтобы у заказчика остался нормативный срок на осмотр и электронное актирование, а у казначейства — на санкционирование оплаты до предельных дат."}, {"@type": "HowToStep", "position": 3, "name": "Подать финальные распоряжения с запасом", "text": "Собственные платежи с лицевого счёта (субподряд, возмещение расходов) направить минимум за неделю до предельной даты с полным комплектом документов — с учётом возможного возврата на доработку."}, {"@type": "HowToStep", "position": 4, "name": "Зафиксировать остатки на 31 декабря", "text": "Составить реестр средств на лицевом счёте с разбивкой: остатки продолжающихся контрактов (нужна потребность) и завершённых (подлежат возврату)."}, {"@type": "HowToStep", "position": 5, "name": "Подтвердить потребность в январе–феврале", "text": "Через заказчика убедиться, что главный распорядитель включил ваши остатки в решение о подтверждении потребности до установленного срока (по остаткам на 01.01.2026 — до 1 мая 2026 года)."}, {"@type": "HowToStep", "position": 6, "name": "Контролировать оплату переходящих обязательств", "text": "Отслеживать перерегистрацию обязательства и доведение лимитов нового года; при просрочке — начислять пени, направлять претензию, при необходимости идти по маршруту взыскания."}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: завершение финансового года и госконтракт", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Финансовый год", "description": "Период исполнения бюджета, в России совпадает с календарным годом; операции по исполнению бюджета завершаются 31 декабря (ст. 242 БК)."}, {"@type": "DefinedTerm", "name": "Лимиты бюджетных обязательств (ЛБО)", "description": "Объём прав заказчика на принятие и оплату обязательств за счёт бюджета; лимиты текущего года прекращают действие 31 декабря."}, {"@type": "DefinedTerm", "name": "Принятие бюджетного обязательства", "description": "Заключение заказчиком контракта (соглашения) в пределах доведённых лимитов; по закупкам федерального бюджета — по общему правилу не позднее 1 июня (п. 10 Положения № 1496)."}, {"@type": "DefinedTerm", "name": "Перерегистрация обязательств", "description": "Учёт неисполненных обязательств отчётного года в новом году для их оплаты за счёт лимитов нового года."}, {"@type": "DefinedTerm", "name": "Остатки целевых средств", "description": "Не использованные на 1 января средства на лицевом счёте участника казначейского сопровождения; используются после подтверждения потребности либо возвращаются в бюджет."}, {"@type": "DefinedTerm", "name": "Подтверждение потребности", "description": "Решение главного распорядителя бюджетных средств о том, что неиспользованные остатки нужны для завершения расчётов; принимается в срок, установленный законом о бюджете."}, {"@type": "DefinedTerm", "name": "Резервный фонд Правительства", "description": "Централизованный фонд, в который в декабре перераспределяются спрогнозированные неиспользуемые лимиты (п. 15(1) Положения № 1496)."}]}
